package intent

import (
	"fmt"
	"strings"
	"time"

	"github.com/gburgyan/aat/graph"
	"github.com/gburgyan/aat/plan"
)

// PostProcess applies deterministic fixes to a plan generated by the LLM.
// It modifies the plan in place.
func PostProcess(p *plan.Plan, g *graph.Graph, ws *WorkflowSelection, prompt string) {
	stepIndex := buildStepIndex(p)

	fixSelectionConfigs(p, g, stepIndex)
	fixDependsOn(p, g, stepIndex)
	fixFilterPrefixes(p)
	fixAssertions(p)
	addCleanupSteps(p, g, stepIndex)
	setMetadata(p, g, prompt)
	populateIntent(p, ws)
}

// buildStepIndex creates a set of identifiers present in the plan.
// It includes both node names (for graph edge lookups) and step IDs
// (for validating dependsOn references in composed plans where step IDs
// differ from node names, e.g., inc0_searchSeatMap vs searchSeatMap).
func buildStepIndex(p *plan.Plan) map[string]bool {
	idx := make(map[string]bool, len(p.Execution.Steps)*2)
	for _, step := range p.Execution.Steps {
		idx[step.Node] = true
		idx[step.StepID()] = true
	}
	return idx
}

// fixDependsOn ensures dependsOn reflects actual data flow and ordering
// constraints. Dependencies come from three sources:
//
//  1. Actual from references in step values and selections (data flow)
//  2. Graph edges for unwired inputs (potential data flow the engine resolves)
//  3. Requires/satisfies token relationships (ordering constraints)
//
// Graph edge deps are only added for inputs that don't already have a from
// reference to a different source. This prevents spurious cycles when a
// sub-workflow input is auto-wired to a parent step but the graph has a
// reverse edge between the sub-workflow nodes.
func fixDependsOn(p *plan.Plan, g *graph.Graph, stepIndex map[string]bool) {
	// Build nodeToStepIDs: maps node name → list of step IDs using that node.
	// For non-composed plans, step IDs == node names. For composed plans,
	// step IDs have prefixes (e.g., inc0_searchSeatMap for node searchSeatMap).
	nodeToStepIDs := map[string][]string{}
	for _, step := range p.Execution.Steps {
		nodeToStepIDs[step.Node] = append(nodeToStepIDs[step.Node], step.StepID())
	}

	// Build per-input edge map: "targetNode.inputName" → set of sourceNodes.
	inputEdgeSources := map[string]map[string]bool{}
	for _, edge := range g.Edges {
		fromNode := splitNodeName(edge.From)
		if fromNode == "" {
			continue
		}
		if inputEdgeSources[edge.To] == nil {
			inputEdgeSources[edge.To] = map[string]bool{}
		}
		inputEdgeSources[edge.To][fromNode] = true
	}

	// Build requires/satisfies deps: targetNode → set of sourceNodes.
	tokenDeps := map[string]map[string]bool{}
	if g.SatisfiersByToken != nil {
		for _, step := range p.Execution.Steps {
			node := g.Nodes[step.Node]
			if node == nil {
				continue
			}
			for _, token := range node.Requires {
				for _, satisfier := range g.SatisfiersByToken[token] {
					if stepIndex[satisfier] && satisfier != step.Node {
						if tokenDeps[step.Node] == nil {
							tokenDeps[step.Node] = map[string]bool{}
						}
						tokenDeps[step.Node][satisfier] = true
					}
				}
			}
		}
	}

	// addStepDeps resolves a dependency reference to actual step IDs and adds
	// them to required. If dep is a node name, it maps to the step IDs using
	// that node (e.g., "addSeatOffer" → ["inc0_addSeatOffer"]). If dep is
	// already a step ID not found in nodeToStepIDs, it's added directly.
	addStepDeps := func(required map[string]bool, dep, selfStepID string) {
		if sids, ok := nodeToStepIDs[dep]; ok {
			for _, sid := range sids {
				if sid != selfStepID {
					required[sid] = true
				}
			}
			return
		}
		// dep is already a step ID (not a node name).
		if stepIndex[dep] && dep != selfStepID {
			required[dep] = true
		}
	}

	for i, step := range p.Execution.Steps {
		stepID := step.StepID()
		node := g.Nodes[step.Node]
		required := map[string]bool{}

		// 1. Dependencies from actual from references in values.
		for _, sv := range step.Values {
			if sv.From != "" {
				addStepDeps(required, splitNodeName(sv.From), stepID)
			}
		}

		// 2. Dependencies from actual from references in named selections.
		for _, sel := range step.Selections {
			if sel.From != "" {
				addStepDeps(required, splitNodeName(sel.From), stepID)
			}
		}

		// 3. Graph edge deps — only for inputs not already wired via from.
		if node != nil {
			for _, inp := range node.Inputs {
				edgeKey := step.Node + "." + inp.Name
				sources := inputEdgeSources[edgeKey]
				if len(sources) == 0 {
					continue
				}

				// Check if this input is already wired.
				sv, hasValue := step.Values[inp.Name]
				if hasValue && (sv.From != "" || sv.FromSelection != "") {
					// Input is wired — deps already handled in steps 1/2.
					continue
				}

				// Input is unwired — add graph edge deps so the engine can
				// resolve it at runtime.
				for sourceNode := range sources {
					addStepDeps(required, sourceNode, stepID)
				}
			}
		}

		// 4. Requires/satisfies token deps (ordering constraints).
		for depNode := range tokenDeps[step.Node] {
			addStepDeps(required, depNode, stepID)
		}

		// 5. Existing valid dependsOn entries (resolved via addStepDeps
		// so bare node names get mapped to prefixed step IDs).
		for _, dep := range step.DependsOn {
			addStepDeps(required, dep, stepID)
		}

		// Build sorted list.
		deps := make([]string, 0, len(required))
		for dep := range required {
			deps = append(deps, dep)
		}
		sortStrings(deps)

		p.Execution.Steps[i].DependsOn = deps
	}
}

// fixSelectionConfigs ensures that inputs fed by select edges have proper
// from/select config (or named selection). If missing, defaults to strategy: first.
func fixSelectionConfigs(p *plan.Plan, g *graph.Graph, stepIndex map[string]bool) {
	// Build select edge index: "toNode.toInput" → "fromNode.fromOutput"
	selectEdges := map[string]string{}
	for _, edge := range g.Edges {
		if edge.Select {
			selectEdges[edge.To] = edge.From
		}
	}

	for i, step := range p.Execution.Steps {
		node := g.Nodes[step.Node]
		if node == nil {
			continue
		}

		if p.Execution.Steps[i].Values == nil {
			p.Execution.Steps[i].Values = map[string]plan.StepValue{}
		}

		// Fix named selection strategies: default empty strategy to "first"
		for selName, sel := range step.Selections {
			if sel.Strategy == "" {
				sel.Strategy = "first"
				p.Execution.Steps[i].Selections[selName] = sel
			}
		}

		for _, inp := range node.Inputs {
			// Skip values that use fromSelection — they're handled by named selections
			if sv, exists := step.Values[inp.Name]; exists && sv.FromSelection != "" {
				continue
			}

			edgeKey := step.Node + "." + inp.Name
			source, isSelect := selectEdges[edgeKey]
			if !isSelect {
				continue
			}

			// Check if source node is in the plan
			sourceNode := splitNodeName(source)
			if !stepIndex[sourceNode] {
				continue
			}

			sv, exists := step.Values[inp.Name]
			if !exists {
				sv = plan.StepValue{}
			}

			// Ensure from is set
			if sv.From == "" {
				sv.From = source
			}

			// Ensure select config exists with a default strategy
			if sv.Select == nil {
				sv.Select = &plan.SelectionConfig{
					Strategy: "first",
					Field:    lookupElementFieldPath(g, source, inp.Name),
				}
			} else if sv.Select.Strategy == "" {
				sv.Select.Strategy = "first"
			}

			p.Execution.Steps[i].Values[inp.Name] = sv
		}
	}
}

// fixFilterPrefixes strips selection-name prefixes from filter expressions.
// LLMs sometimes generate filters like "catalogProductOffering.carrier == 'QF'"
// when the correct form is "carrier == 'QF'" (field names are relative to the
// selected element, not qualified by selection name).
func fixFilterPrefixes(p *plan.Plan) {
	for i, step := range p.Execution.Steps {
		for selName, sel := range step.Selections {
			if sel.Filter == "" {
				continue
			}
			prefix := selName + "."
			if strings.Contains(sel.Filter, prefix) {
				sel.Filter = strings.ReplaceAll(sel.Filter, prefix, "")
				p.Execution.Steps[i].Selections[selName] = sel
			}
		}
		for name, sv := range step.Values {
			if sv.Select != nil && sv.Select.Filter != "" {
				// For inline selections, the "selection name" is the value name
				prefix := name + "."
				if strings.Contains(sv.Select.Filter, prefix) {
					sv.Select.Filter = strings.ReplaceAll(sv.Select.Filter, prefix, "")
					p.Execution.Steps[i].Values[name] = sv
				}
			}
		}
	}
}

// validAssertionTypes is the set of recognized mechanical assertion types.
var validAssertionTypes = map[string]bool{
	"status":      true,
	"schema":      true,
	"fieldExists": true,
	"fieldEquals": true,
	"predicate":   true,
}

// fixAssertions removes mechanical assertions with empty or unknown types and
// ensures every step has at least a status assertion. LLMs sometimes produce
// assertions with missing type fields; this cleans them up.
//
// For expectFailure steps, the default status assertion uses the first expected
// failure code instead of 200 (which would contradict the expected failure).
func fixAssertions(p *plan.Plan) {
	for i := range p.Execution.Steps {
		step := &p.Execution.Steps[i]
		if step.Assertions == nil {
			step.Assertions = &plan.Assertions{}
		}

		// Filter to valid assertions only.
		var valid []plan.MechanicalAssertion
		hasStatus := false
		for _, a := range step.Assertions.Mechanical {
			if !validAssertionTypes[a.Type] {
				continue
			}
			if a.Type == "status" {
				hasStatus = true
			}
			valid = append(valid, a)
		}

		// Ensure at least a status assertion.
		if !hasStatus {
			defaultStatus := 200
			if step.ExpectFailure != nil && len(step.ExpectFailure.Status) > 0 {
				defaultStatus = step.ExpectFailure.Status[0]
			}
			valid = append([]plan.MechanicalAssertion{{
				Type:   "status",
				Expect: defaultStatus,
			}}, valid...)
		}

		step.Assertions.Mechanical = valid
	}
}

// addCleanupSteps ensures cleanup steps exist for nodes that have Cleanup fields.
func addCleanupSteps(p *plan.Plan, g *graph.Graph, stepIndex map[string]bool) {
	// Build set of existing cleanup nodes
	existingCleanup := map[string]bool{}
	for _, cs := range p.Execution.Cleanup {
		existingCleanup[cs.Node] = true
	}

	for _, step := range p.Execution.Steps {
		node := g.Nodes[step.Node]
		if node == nil || node.Cleanup == "" {
			continue
		}

		if !existingCleanup[node.Cleanup] {
			p.Execution.Cleanup = append(p.Execution.Cleanup, plan.CleanupStep{
				Node:  node.Cleanup,
				RunOn: "always",
			})
			existingCleanup[node.Cleanup] = true
		}
	}
}

// setMetadata populates plan metadata fields.
func setMetadata(p *plan.Plan, g *graph.Graph, prompt string) {
	setMetadataWithTime(p, g, prompt, time.Now())
}

// populateIntent transfers constraint classification from WorkflowSelection into the plan.
func populateIntent(p *plan.Plan, ws *WorkflowSelection) {
	if ws == nil {
		return
	}

	if p.Intent.Description == "" {
		p.Intent.Description = ws.Description
	}

	// Only backfill constraints from WorkflowSelection if the LLM didn't already
	// populate them in the YAML. This prevents duplication when the LLM
	// includes constraints (it has full visibility of the selection in the prompt).
	populateConstraints(p, ws.Constraints)
}

// populateIntentFromGoal transfers constraint classification from GoalAnalysis
// into the plan. Used by BuildSkeleton for backward-chaining-based scaffolding.
func populateIntentFromGoal(p *plan.Plan, ga *GoalAnalysis) {
	if ga == nil {
		return
	}

	p.Intent.Goal = ga.Goal
	if p.Intent.Description == "" {
		p.Intent.Description = ga.Description
	}

	populateConstraints(p, ga.Constraints)
}

// populateConstraints backfills constraints from a ConstraintSet into the plan.
func populateConstraints(p *plan.Plan, cs ConstraintSet) {
	if p.Intent.Constraints == nil {
		if len(cs.Hard) > 0 || len(cs.Soft) > 0 || len(cs.Free) > 0 {
			p.Intent.Constraints = &plan.Constraints{}
			for _, h := range cs.Hard {
				p.Intent.Constraints.Hard = append(p.Intent.Constraints.Hard, plan.Constraint{
					Name:        h.Name,
					Description: h.Description,
					AppliesTo:   h.AppliesTo,
				})
			}
			for _, s := range cs.Soft {
				p.Intent.Constraints.Soft = append(p.Intent.Constraints.Soft, plan.Constraint{
					Name:        s.Name,
					Description: s.Description,
					AppliesTo:   s.AppliesTo,
				})
			}
			p.Intent.Constraints.Free = append(p.Intent.Constraints.Free, cs.Free...)
		}
	}

	// Resolve constraint AppliesTo references: in composed plans the LLM uses
	// bare node names (e.g., "searchSeatMap.workbenchId") but actual step IDs
	// have prefixes (e.g., "inc0_searchSeatMap"). Map node names → step IDs.
	resolveConstraintRefs(p)
}

// resolveConstraintRefs rewrites constraint AppliesTo entries so that bare
// node names are replaced with the actual step IDs from the plan. This is
// needed for composed plans where step IDs are prefixed.
func resolveConstraintRefs(p *plan.Plan) {
	if p.Intent.Constraints == nil {
		return
	}

	// Build nodeToStepID: node name → first step ID using that node.
	nodeToStepID := map[string]string{}
	for _, step := range p.Execution.Steps {
		sid := step.StepID()
		if sid != step.Node {
			// Only populate for steps where the step ID differs from the node
			// name (i.e., composed/prefixed steps).
			if _, exists := nodeToStepID[step.Node]; !exists {
				nodeToStepID[step.Node] = sid
			}
		}
	}
	if len(nodeToStepID) == 0 {
		return // No prefixed steps — nothing to resolve.
	}

	resolveRefs := func(refs []string) []string {
		resolved := make([]string, len(refs))
		for i, ref := range refs {
			stepRef := ref
			suffix := ""
			if idx := strings.Index(ref, "."); idx > 0 {
				stepRef = ref[:idx]
				suffix = ref[idx:] // includes the dot
			}
			if mapped, ok := nodeToStepID[stepRef]; ok {
				resolved[i] = mapped + suffix
			} else {
				resolved[i] = ref
			}
		}
		return resolved
	}

	for i := range p.Intent.Constraints.Hard {
		p.Intent.Constraints.Hard[i].AppliesTo = resolveRefs(p.Intent.Constraints.Hard[i].AppliesTo)
	}
	for i := range p.Intent.Constraints.Soft {
		p.Intent.Constraints.Soft[i].AppliesTo = resolveRefs(p.Intent.Constraints.Soft[i].AppliesTo)
	}
}

// BuildSkeleton constructs a deterministic plan scaffold from the graph,
// backward chain result, and goal analysis. All structural elements (steps,
// dependsOn, from refs, select configs, cleanup, metadata, intent) are
// computed from the graph. Only literal values for unfed inputs are left
// empty for the LLM to fill.
func BuildSkeleton(g *graph.Graph, cr *graph.ChainResult, ga *GoalAnalysis, prompt string, now time.Time) *plan.Plan {
	p := &plan.Plan{}

	// Build edge indexes from the chain's edges (not the full graph).
	// allEdges: "toNode.toInput" → "fromNode.fromOutput"
	allEdges := map[string]string{}
	// selectEdges: same but only for select:true edges
	selectEdges := map[string]string{}
	for _, edge := range cr.Edges {
		allEdges[edge.To] = edge.From
		if edge.Select {
			selectEdges[edge.To] = edge.From
		}
	}

	// Build step index from chain nodes.
	stepIndex := map[string]bool{}
	for _, name := range cr.Nodes {
		stepIndex[name] = true
	}

	// Build edge-based dependency map: targetNode → set of sourceNodes
	edgeDeps := map[string]map[string]bool{}
	for _, edge := range cr.Edges {
		fromNode := splitNodeName(edge.From)
		toNode := splitNodeName(edge.To)
		if fromNode == "" || toNode == "" {
			continue
		}
		if edgeDeps[toNode] == nil {
			edgeDeps[toNode] = map[string]bool{}
		}
		edgeDeps[toNode][fromNode] = true
	}

	// Include requires edges in dependency map.
	for _, re := range cr.RequiresEdges {
		if edgeDeps[re.To] == nil {
			edgeDeps[re.To] = map[string]bool{}
		}
		edgeDeps[re.To][re.From] = true
	}

	// Create steps in chain order.
	for _, nodeName := range cr.Nodes {
		node := g.Nodes[nodeName]
		if node == nil {
			continue
		}

		step := plan.Step{
			Node:   nodeName,
			IsGoal: ga != nil && nodeName == ga.Goal,
			Values: map[string]plan.StepValue{},
		}

		// Compute dependsOn from chain edges.
		deps := map[string]bool{}
		for dep := range edgeDeps[nodeName] {
			if stepIndex[dep] && dep != nodeName {
				deps[dep] = true
			}
		}
		depList := make([]string, 0, len(deps))
		for dep := range deps {
			depList = append(depList, dep)
		}
		sortStrings(depList)
		step.DependsOn = depList

		// Collect select-edge inputs grouped by source to detect multi-field extraction.
		// source → []inputName
		selectBySource := map[string][]string{}
		for _, inp := range node.Inputs {
			edgeKey := nodeName + "." + inp.Name
			if source, isSelect := selectEdges[edgeKey]; isSelect {
				sourceNode := splitNodeName(source)
				if stepIndex[sourceNode] {
					selectBySource[source] = append(selectBySource[source], inp.Name)
				}
			}
		}

		// Create named selections for sources with 2+ inputs.
		namedSources := map[string]string{} // source → selection name
		for source, inputs := range selectBySource {
			if len(inputs) >= 2 {
				selName := deriveSelectionName(source)
				if step.Selections == nil {
					step.Selections = map[string]plan.StepSelection{}
				}
				step.Selections[selName] = plan.StepSelection{
					From:     source,
					Strategy: "first",
				}
				namedSources[source] = selName
			}
		}

		// For each input, wire up from/select, fromSelection, or leave empty for LLM.
		for _, inp := range node.Inputs {
			edgeKey := nodeName + "." + inp.Name

			if source, isSelect := selectEdges[edgeKey]; isSelect {
				sourceNode := splitNodeName(source)
				if !stepIndex[sourceNode] {
					continue
				}
				if selName, isNamed := namedSources[source]; isNamed {
					// Use named selection
					fieldName := lookupElementFieldPath(g, source, inp.Name)
					step.Values[inp.Name] = plan.StepValue{
						FromSelection: selName + "." + fieldName,
					}
				} else {
					// Single input from this source: use old-style from+select
					step.Values[inp.Name] = plan.StepValue{
						From: source,
						Select: &plan.SelectionConfig{
							Strategy: "first",
							Field:    lookupElementFieldPath(g, source, inp.Name),
						},
					}
				}
			} else if source, hasEdge := allEdges[edgeKey]; hasEdge {
				// Scalar edge: set from only.
				sourceNode := splitNodeName(source)
				if stepIndex[sourceNode] {
					step.Values[inp.Name] = plan.StepValue{
						From: source,
					}
				}
			} else if inp.Default != nil {
				// Graph-level default: set as default value.
				step.Values[inp.Name] = plan.StepValue{
					Default: inp.Default,
				}
			}
			// else: unfed input → leave absent, LLM will fill it.
		}

		p.Execution.Steps = append(p.Execution.Steps, step)
	}

	// Add cleanup steps.
	addCleanupSteps(p, g, stepIndex)

	// Set metadata and intent.
	setMetadataWithTime(p, g, prompt, now)
	populateIntentFromGoal(p, ga)

	return p
}

// UnfedInputs returns a list of "node.input" keys that have no edge feeding
// them and no graph-level default — these need LLM-provided values.
func UnfedInputs(g *graph.Graph, cr *graph.ChainResult) []string {
	// Build fed set from chain edges.
	fed := map[string]bool{}
	for _, edge := range cr.Edges {
		fed[edge.To] = true
	}

	var unfed []string
	for _, nodeName := range cr.Nodes {
		node := g.Nodes[nodeName]
		if node == nil {
			continue
		}
		for _, inp := range node.Inputs {
			key := nodeName + "." + inp.Name
			if fed[key] {
				continue
			}
			if inp.Optional {
				continue
			}
			if inp.Default != nil {
				continue
			}
			unfed = append(unfed, fmt.Sprintf("%s.%s (%s)", nodeName, inp.Name, inp.Type))
		}
	}
	return unfed
}

// MergeLLMValues merges LLM-provided creative content into the skeleton plan,
// matching steps by node name. The skeleton's structural fields are authoritative;
// the LLM only adds/overrides values, descriptions, assertions, selection strategy
// refinements, and retry config.
//
// The unfed parameter gates which new inputs (not already in the skeleton) are
// accepted; see MergeLLMValuesWithIDs for details. If unfed is nil, all
// LLM-provided new values are accepted (legacy behavior).
func MergeLLMValues(skeleton, llmPlan *plan.Plan, unfed map[string]bool) {
	// Build index of LLM steps by node name.
	llmSteps := map[string]*plan.Step{}
	for i := range llmPlan.Execution.Steps {
		llmSteps[llmPlan.Execution.Steps[i].Node] = &llmPlan.Execution.Steps[i]
	}

	for i := range skeleton.Execution.Steps {
		skelStep := &skeleton.Execution.Steps[i]
		llmStep, ok := llmSteps[skelStep.Node]
		if !ok {
			continue
		}

		// Accept description from LLM.
		if llmStep.Description != "" {
			skelStep.Description = llmStep.Description
		}

		// Accept assertions from LLM.
		if llmStep.Assertions != nil {
			skelStep.Assertions = llmStep.Assertions
		}

		// Accept retry config from LLM.
		if llmStep.Retry != nil {
			skelStep.Retry = llmStep.Retry
		}

		// Merge named selection strategy overrides from LLM.
		if len(skelStep.Selections) > 0 && len(llmStep.Selections) > 0 {
			for selName, llmSel := range llmStep.Selections {
				skelSel, exists := skelStep.Selections[selName]
				if !exists {
					continue // ignore selections the skeleton doesn't have
				}
				// Accept strategy/filter/sortField/prompt overrides
				if llmSel.Strategy != "" {
					skelSel.Strategy = llmSel.Strategy
				}
				if llmSel.Filter != "" {
					skelSel.Filter = llmSel.Filter
				}
				if llmSel.SortField != "" {
					skelSel.SortField = llmSel.SortField
				}
				if llmSel.Prompt != "" {
					skelSel.Prompt = llmSel.Prompt
				}
				if llmSel.Index != 0 {
					skelSel.Index = llmSel.Index
				}
				skelStep.Selections[selName] = skelSel
			}
		}

		// Merge values.
		if llmStep.Values == nil {
			continue
		}
		if skelStep.Values == nil {
			skelStep.Values = map[string]plan.StepValue{}
		}

		for inputName, llmVal := range llmStep.Values {
			skelVal, exists := skelStep.Values[inputName]

			if !exists {
				// Only accept new literals for inputs that genuinely need values.
				// Reject hallucinated literals for inputs that will be auto-wired
				// from graph edges at runtime.
				key := skelStep.StepID() + "." + inputName
				if llmVal.Default != nil && (unfed == nil || unfed[key]) {
					skelStep.Values[inputName] = plan.StepValue{
						Default: llmVal.Default,
					}
				}
				continue
			}

			// Skeleton has an entry. Merge based on what skeleton has.
			if skelVal.FromSelection != "" {
				// Named selection: skeleton is authoritative for fromSelection.
				// LLM can't change the structural ref. Skip.
				continue
			} else if skelVal.From != "" && skelVal.Select != nil {
				// Select edge: accept strategy/filter/sortField/index/prompt overrides.
				if llmVal.Select != nil {
					if llmVal.Select.Strategy != "" {
						skelVal.Select.Strategy = llmVal.Select.Strategy
					}
					if llmVal.Select.Filter != "" {
						skelVal.Select.Filter = llmVal.Select.Filter
					}
					if llmVal.Select.SortField != "" {
						skelVal.Select.SortField = llmVal.Select.SortField
					}
					if llmVal.Select.Index != 0 {
						skelVal.Select.Index = llmVal.Select.Index
					}
					if llmVal.Select.Prompt != "" {
						skelVal.Select.Prompt = llmVal.Select.Prompt
					}
				}
				skelStep.Values[inputName] = skelVal
			} else if skelVal.From != "" {
				// Scalar from ref: skeleton is authoritative, ignore LLM changes.
				// But if LLM tries to add Select to a scalar edge, ignore it.
			} else {
				// Graph default or empty: accept LLM literal override.
				if llmVal.Default != nil {
					skelVal.Default = llmVal.Default
				}
				skelStep.Values[inputName] = skelVal
			}
		}
	}
}

// setMetadataWithTime populates plan metadata with a specific time.
func setMetadataWithTime(p *plan.Plan, g *graph.Graph, prompt string, now time.Time) {
	p.Metadata.Prompt = prompt
	p.Metadata.GraphVersion = g.Version
	if p.Metadata.Created.IsZero() {
		p.Metadata.Created = now
	}
}

// lookupElementFieldPath finds the elementField name for an input fed by a
// select edge. It returns the elementField Name (not the gjson path) so that
// plans remain decoupled from response structure. The engine resolves the
// name to a gjson path at runtime via resolveElementFieldPath.
// Falls back to inputName if no matching elementField exists.
func lookupElementFieldPath(g *graph.Graph, sourceRef, inputName string) string {
	srcNode := splitNodeName(sourceRef)
	srcField := sourceRef[len(srcNode)+1:]
	node := g.Nodes[srcNode]
	if node == nil {
		return inputName
	}
	for _, out := range node.Outputs {
		if out.Name == srcField {
			for _, ef := range out.ElementFields {
				if ef.Name == inputName {
					return ef.Name
				}
			}
			break
		}
	}
	return inputName
}

// deriveSelectionName creates a name for a named selection from the source
// reference. It takes the last segment (e.g., "catalogOfferings" from
// "searchFlights.catalogOfferings") and makes it singular-ish.
func deriveSelectionName(source string) string {
	parts := strings.SplitN(source, ".", 2)
	if len(parts) < 2 {
		return "selection"
	}
	name := parts[1]
	// Simple singularization: strip trailing 's' if it exists
	if len(name) > 1 && name[len(name)-1] == 's' {
		name = name[:len(name)-1]
	}
	return name
}

// splitNodeName extracts the node name from a "node.field" reference.
func splitNodeName(ref string) string {
	parts := strings.SplitN(ref, ".", 2)
	if len(parts) == 0 {
		return ""
	}
	return parts[0]
}

// blankBrokenFromSelections scans the plan for fromSelection values whose
// field component is not a valid elementField on the source output. Any such
// values have their FromSelection cleared (making them unfed inputs for the
// LLM retry). Returns the list of blanked "step.input" keys and a description
// of what the correct elementFields are for the retry prompt.
func blankBrokenFromSelections(p *plan.Plan, g *graph.Graph) (blanked []string, hints []string) {
	outputsByNode := make(map[string]map[string]graph.Output)
	for name, node := range g.Nodes {
		outs := make(map[string]graph.Output, len(node.Outputs))
		for _, out := range node.Outputs {
			outs[out.Name] = out
		}
		outputsByNode[name] = outs
	}

	for i, step := range p.Execution.Steps {
		for inputName, sv := range step.Values {
			if sv.FromSelection == "" {
				continue
			}
			selName, fieldName := plan.ParseFromSelection(sv.FromSelection)
			if fieldName == "" {
				continue
			}
			sel, selExists := step.Selections[selName]
			if !selExists || sel.From == "" {
				continue
			}
			parts := strings.SplitN(sel.From, ".", 2)
			if len(parts) != 2 {
				continue
			}
			srcNode, srcField := parts[0], parts[1]
			outs, ok := outputsByNode[srcNode]
			if !ok {
				continue
			}
			out, outExists := outs[srcField]
			if !outExists || len(out.ElementFields) == 0 {
				continue
			}
			found := false
			for _, ef := range out.ElementFields {
				if ef.Name == fieldName {
					found = true
					break
				}
			}
			if !found {
				blanked = append(blanked, step.Node+"."+inputName)
				sv.FromSelection = ""
				p.Execution.Steps[i].Values[inputName] = sv

				// Build hint showing available elementFields
				var efNames []string
				for _, ef := range out.ElementFields {
					efNames = append(efNames, ef.Name)
				}
				hints = append(hints, fmt.Sprintf(
					"Available elementFields for %s.%s: %s",
					srcNode, srcField, strings.Join(efNames, ", ")))
			}
		}
	}
	return blanked, hints
}

// restoreBlankedFromSelections copies fromSelection values from the LLM plan
// into the skeleton for inputs that were blanked during retry preparation.
// This is needed because MergeLLMValues treats fromSelection as structural
// and won't accept it from the LLM.
func restoreBlankedFromSelections(skeleton, llmPlan *plan.Plan, blanked []string) {
	blankedSet := make(map[string]bool, len(blanked))
	for _, b := range blanked {
		blankedSet[b] = true
	}

	// Build LLM step index
	llmSteps := map[string]*plan.Step{}
	for i := range llmPlan.Execution.Steps {
		llmSteps[llmPlan.Execution.Steps[i].Node] = &llmPlan.Execution.Steps[i]
	}

	for i, step := range skeleton.Execution.Steps {
		llmStep, ok := llmSteps[step.Node]
		if !ok {
			continue
		}
		for inputName, skelVal := range step.Values {
			key := step.Node + "." + inputName
			if !blankedSet[key] {
				continue
			}
			if llmVal, exists := llmStep.Values[inputName]; exists && llmVal.FromSelection != "" {
				skelVal.FromSelection = llmVal.FromSelection
				skeleton.Execution.Steps[i].Values[inputName] = skelVal
			}
		}
	}
}

// sortStrings sorts a string slice in place.
func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		key := s[i]
		j := i - 1
		for j >= 0 && s[j] > key {
			s[j+1] = s[j]
			j--
		}
		s[j+1] = key
	}
}
